    case BUTTON_PRESS_DOWN: {
        ESP_LOGI(TAG, "Press down:%d", press_down_count);

        if (press_down_count == 0) {
            first_press_time_ms = now_ms;
        }

        press_down_count++;

        if (now_ms - first_press_time_ms > PRESS_DOWN_TIME_WINDOW_MS) {
            press_down_count = 1;
            first_press_time_ms = now_ms;
