[{"ref":"ev:9873f744385e893c","path":"main/boards/esp_vocat/ui_bridge.cc","line":315,"end_line":328,"excerpt":"
static void ui_bridge_base_container_event_cb(lv_event_t *e)
{
    lv_event_code_t code = lv_event_get_code(e);
    if (code == LV_EVENT_CLICKED) {
        auto &app = Application::GetInstance();
        if (app.GetDeviceState() == kDeviceStateStarting &&
            !WifiStation::GetInstance().IsConnected()) {
            static_cast<WifiBoard&>(Board::GetInstance()).ResetWifiConfiguration();
        } else {
            app.ToggleChatState();
        }
    }
}","origin":"official_git_blob"},{"ref":"ev:19700c549b6ef007","path":"main/application.cc","line":269,"end_line":293,"excerpt":"
    if (device_state_ == kDeviceStateIdle) {
        Schedule([this]() {
            if (!protocol_->IsAudioChannelOpened()) {
                SetDeviceState(kDeviceStateConnecting);
                if (!protocol_->OpenAudioChannel()) {
                    return;
                }
            }

            SetListeningMode(aec_mode_ == kAecOff ? kListeningModeAutoStop : kListeningModeRealtime);
        });
    } else if (device_state_ == kDeviceStateSpeaking) {
        Schedule([this]() {
            AbortSpeaking(kAbortReasonNone);
        });
    } else if (device_state_ == kDeviceStateListening) {
        Schedule([this]() {
            protocol_->CloseAudioChannel();
        });
    }
}

